/* Flash cards USMLE: Pharmacology (452 cartões originais). [id, pergunta, resposta, explicação em português] */
window.USMLE_DATA = window.USMLE_DATA || {};
window.USMLE_DATA["pharmacology"] = [{"name":"Autonomic Drugs (Part 1)","cards":[["3zo6xy8ib","How is acetylcholine synthesized and released?","Choline + acetyl-CoA by choline acetyltransferase; stored in vesicles; released with Ca2+ influx; degraded by acetylcholinesterase.","Síntese e liberação da acetilcolina."],["z712cpprv","What blocks choline uptake into cholinergic neurons?","Hemicholinium.","Hemicolínio."],["jqh8hmhqw","What blocks ACh vesicle storage?","Vesamicol.","Vesamicol."],["1vkjll5mo","What blocks ACh release?","Botulinum toxin.","Toxina botulínica."],["3lhvfkeba","How is norepinephrine synthesized?","Tyrosine to DOPA (tyrosine hydroxylase, rate limiting), DOPA to dopamine, dopamine to NE (dopamine beta-hydroxylase) in vesicles.","Síntese da noradrenalina."],["1nj5h551x","What inhibits tyrosine hydroxylase?","Metyrosine.","Metirosina."],["hc4u8ccrc","What inhibits vesicular monoamine transporter (VMAT)?","Reserpine (depletes NE), tetrabenazine.","Reserpina."],["vfxbcx5vx","What drugs increase NE release?","Amphetamine, ephedrine (indirect sympathomimetics).","Anfetamina e efedrina."],["1ei9gek43","What drugs block NE reuptake?","Cocaine, TCAs, SNRIs.","Cocaína e tricíclicos."],["1jgzd6hh0","What blocks NE release (inhibits exocytosis)?","Guanethidine (and bretylium).","Guanetidina."],["1o6ok481v","What is the mechanism of bethanechol?","Direct muscarinic agonist, resistant to AChE; activates bladder and bowel smooth muscle.","Agonista muscarínico."],["es3nga15f","Uses of bethanechol?","Postoperative ileus, neurogenic ileus, urinary retention.","Retenção urinária e íleo."],["y67vff85t","Mechanism and use of carbachol?","Direct cholinergic agonist (muscarinic and nicotinic); constricts pupil, relief of intraocular pressure.","Miose e glaucoma."],["1x3fxbz1t","Mechanism and use of methacholine?","Muscarinic agonist; bronchial challenge test to diagnose asthma.","Teste de broncoprovocação."],["1bqp3202i","Mechanism and use of pilocarpine?","Muscarinic agonist; potent stimulator of sweat, tears, saliva; glaucoma (open and closed angle), xerostomia (Sjögren).","Glaucoma e boca seca."],["7567u5nn7","Mechanism of indirect cholinergic agonists?","Anticholinesterases increase endogenous ACh.","Inibem a acetilcolinesterase."],["1bt9dbw1d","Uses of donepezil, rivastigmine, galantamine?","Alzheimer disease (cross BBB).","Doença de Alzheimer."],["1y3c0xjp8","Uses of edrophonium?","Historically to diagnose myasthenia gravis (very short acting).","Diagnóstico de miastenia."],["dr2qjl1s6","Uses of neostigmine?","Postoperative and neurogenic ileus, urinary retention, myasthenia gravis, reversal of neuromuscular blockade; does not cross BBB.","Reverter bloqueio neuromuscular."],["ixsil4kpv","Uses of physostigmine?","Antidote for anticholinergic toxicity; crosses BBB (tertiary amine).","Antídoto anticolinérgico."],["1xotw4cop","Uses of pyridostigmine?","Myasthenia gravis long-acting; does not cross BBB.","Miastenia gravis."],["ejvvsv9xb","Adverse effects of cholinesterase inhibitors?","Cholinergic excess: diarrhea, urination, miosis, bronchospasm, bradycardia, lacrimation, sweating, salivation.","Excesso colinérgico."],["gfsl2w1yv","What is organophosphate poisoning?","Irreversible AChE inhibition (insecticides like parathion, malathion; sarin nerve gas): DUMBELSS plus muscle paralysis and CNS effects.","Intoxicação por organofosforados."],["j3zff6nvw","What is the antidote for organophosphate poisoning?","Atropine (competitive muscarinic antagonist) plus pralidoxime (regenerates AChE if given early before aging).","Atropina e pralidoxima."],["23iqpuq0a","Why is pralidoxime given early?","AChE-organophosphate complex ages and becomes irreversible.","Antes do envelhecimento da enzima."],["w222tmg8o","What are muscarinic antagonists used for in the eye?","Atropine, homatropine, tropicamide: mydriasis and cycloplegia.","Midríase e cicloplegia."],["f3v6fcxdc","Uses of benztropine and trihexyphenidyl?","Parkinson disease tremor and acute dystonia.","Parkinson e distonia."],["18tusqvnp","Uses of glycopyrrolate?","Reduce airway secretions preoperatively; drooling; peptic ulcer (no CNS penetration).","Reduz secreções."],["yr4ufd10p","Uses of hyoscyamine and dicyclomine?","Antispasmodics for IBS.","Antiespasmódicos."],["15bgkuo1b","Uses of ipratropium and tiotropium?","COPD and asthma (bronchodilation).","DPOC."],["1h824s2jk","Uses of oxybutynin, solifenacin, tolterodine?","Overactive bladder (urge incontinence).","Bexiga hiperativa."],["1ba3hy9ah","Uses of scopolamine?","Motion sickness.","Cinetose."],["1ns6ppg6d","Uses and adverse effects of atropine?","Bradycardia (increases HR), organophosphate poisoning, mydriasis; adverse: hot as a hare, dry as a bone, red as a beet, blind as a bat, mad as a hatter, urinary retention, tachycardia.","Bradicardia e intoxicação colinérgica."],["c471gg1pi","Why is atropine dangerous in elderly men?","Urinary retention (BPH) and acute angle-closure glaucoma.","Retenção urinária e glaucoma."],["ymxykghb5","What causes jimson weed toxicity?","Anticholinergic (gardener's pupil): mydriasis, delirium, hyperthermia.","Toxicidade anticolinérgica."],["1rpwvpr1q","What are direct sympathomimetics?","Albuterol, dobutamine, dopamine, epinephrine, isoproterenol, norepinephrine, phenylephrine.","Simpaticomiméticos diretos."],["1eoeuobe3","What receptors does epinephrine act on and its uses?","Beta > alpha at low doses, alpha at high doses; anaphylaxis, asthma, cardiac arrest, hypotension, local anesthetic adjunct.","Anafilaxia e parada cardíaca."],["dxgjqwfmx","What receptors does norepinephrine act on and its uses?","Alpha1 > alpha2 > beta1; septic shock (hypotension); may cause reflex bradycardia.","Choque séptico."],["jpp1isxxo","What receptors does dopamine act on?","D1 = D2 > beta > alpha (dose dependent); cardiogenic shock, unstable bradycardia.","Dose-dependente."],["117d34i1b","What receptors does dobutamine act on and its uses?","Beta1 > beta2, alpha; acute heart failure (inotropic), cardiac stress testing.","Inotrópico."],["1ff1e931e","What receptors does isoproterenol act on and its uses?","Beta1 = beta2; torsades de pointes (increases HR shortening QT), electrophysiologic evaluation of tachyarrhythmias; can worsen ischemia.","Torsades."],["1ye4s0v1k","What receptors does phenylephrine act on and its uses?","Alpha1 > alpha2; hypotension (vasoconstrictor), mydriasis, nasal decongestant; reflex bradycardia.","Vasoconstritor e descongestionante."],["1c1ewumim","What receptors does albuterol act on and its uses?","Beta2 > beta1; acute asthma and COPD exacerbation; tremor, tachycardia, hypokalemia.","Broncodilatador de resgate."],["pdsfky99z","What receptors does salmeterol act on and its uses?","Long-acting beta2 agonist; asthma maintenance (with inhaled steroid), COPD.","Beta2 de longa ação."],["hkpgu31hp","What receptors does terbutaline act on and its uses?","Beta2 agonist; acute asthma, historically tocolysis.","Beta2."],["1qubylh1t","What receptors does mirabegron act on?","Beta3 agonist; overactive bladder (detrusor relaxation).","Beta3; bexiga hiperativa."],["1tk9u2017","What are indirect sympathomimetics?","Amphetamine, cocaine, ephedrine (and pseudoephedrine, tyramine).","Simpaticomiméticos indiretos."],["1m5gqpv1a","Mechanism of amphetamine?","Indirect general agonist: reverses NE and dopamine transporters, releasing stored catecholamines; ADHD, narcolepsy, obesity.","Libera catecolaminas."],["ybv7t71to","Mechanism and effects of cocaine?","Indirect agonist inhibiting NE, dopamine, serotonin reuptake; vasoconstriction, local anesthesia; caution with beta-blockers in cocaine intoxication.","Bloqueia recaptação; vasoconstrição."],["skyzvj1xt","Mechanism and uses of ephedrine?","Releases stored catecholamines (indirect agonist) and direct effects; nasal decongestion, urinary incontinence, hypotension.","Descongestionante e hipotensão."],["tl5pjs1wf","What is tyramine and why is it dangerous with MAOIs?","Indirect sympathomimetic in aged cheeses and wine, normally metabolized by MAO; with MAOIs causes hypertensive crisis.","Crise hipertensiva com IMAO."],["1czgjfj1a","What are the sympatholytics (alpha2 agonists)?","Clonidine, guanfacine, methyldopa, tizanidine.","Agonistas alfa-2."],["1gkkaz6x4","Uses of clonidine and guanfacine?","Hypertensive urgency, ADHD, Tourette syndrome, opioid and nicotine withdrawal symptoms.","Hipertensão, TDAH, abstinência."],["cl5w4k9wt","Adverse effects of clonidine?","CNS depression, bradycardia, hypotension, respiratory depression, miosis; rebound hypertension with abrupt cessation.","Sedação e hipertensão rebote."],["1qwg3lk1a","Uses of methyldopa?","Hypertension in pregnancy.","Hipertensão na gestação."],["1hosdni61","Adverse effects of methyldopa?","Direct Coombs-positive hemolysis, drug-induced lupus, hyperprolactinemia.","Hemólise e lúpus induzido."],["1jricrr5h","Mechanism and use of tizanidine?","Central alpha2 agonist; spasticity relief.","Espasticidade."],["1dtvfvzjd","What are nonselective alpha-blockers?","Phenoxybenzamine (irreversible) and phentolamine (reversible).","Alfa-bloqueadores não seletivos."],["14507dv1r","Uses of phenoxybenzamine?","Pheochromocytoma (used preoperatively) to prevent catecholamine hypertensive crisis.","Feocromocitoma."],["16rtjnt66","Uses of phentolamine?","Treat epinephrine extravasation, cocaine-induced hypertension, MAOI-tyramine crisis.","Crise hipertensiva e extravasamento."],["8uh3g7ctq","Adverse effects of nonselective alpha-blockers?","Orthostatic hypotension, reflex tachycardia.","Hipotensão postural."],["g3ybjlj64","What are alpha1-selective blockers?","Prazosin, terazosin, doxazosin, tamsulosin (-osin).","Bloqueadores alfa-1."],["1hl1jskl2","Uses of alpha1-selective blockers?","Urinary symptoms of BPH, PTSD nightmares (prazosin), hypertension (except tamsulosin).","Hiperplasia prostática e pesadelos."],["17f2hg21o","Adverse effects of alpha1-selective blockers?","First-dose orthostatic hypotension, dizziness, headache; tamsulosin: floppy iris during cataract surgery.","Hipotensão na primeira dose."],["56oxe1i1s","What is the alpha2-selective blocker and its use?","Mirtazapine (antidepressant): sedation, increased appetite, weight gain.","Mirtazapina."],["1fy1lrr93","What are beta1-selective blockers?","Acebutolol (partial agonist), atenolol, betaxolol, bisoprolol, esmolol, metoprolol, nebivolol (A BEAM).","Betabloqueadores seletivos."],["hifzbdug6","What are nonselective beta-blockers?","Nadolol, pindolol (partial agonist), propranolol, timolol (NPPT).","Betabloqueadores não seletivos."],["2snaam1t7","What are beta-blockers with alpha1 activity?","Carvedilol and labetalol.","Carvedilol e labetalol."],["utvbxa1v3","Which beta-blocker causes NO-mediated vasodilation?","Nebivolol.","Nebivolol."],["9r9njlfbr","Uses of beta-blockers?","Angina, MI, SVT, heart failure, hypertension, glaucoma, hypertrophic cardiomyopathy, thyrotoxicosis, variceal bleeding, migraine, essential tremor, performance anxiety.","Muitos usos cardiovasculares."],["1mkkxg718","Adverse effects of beta-blockers?","Erectile dysfunction, cardiovascular (bradycardia, AV block, HF), CNS (seizures, sleep), dyslipidemia, masking of hypoglycemia, asthma/COPD exacerbation.","Disfunção erétil, bradicardia, broncoespasmo."],["1afetl519","Why are beta1-selective blockers preferred in comorbid pulmonary disease?","Less beta2 blockade (less bronchospasm).","Menos broncoespasmo."],["119a4y11t","What is the antidote for beta-blocker overdose?","Glucagon (and atropine, IV fluids, calcium, insulin with glucose).","Glucagon."],["uwgepvzmn","Which beta-blocker is used in glaucoma?","Timolol (decreases aqueous humor production).","Timolol."],["1qxn1daph","Which beta-blocker is used for variceal bleeding prophylaxis?","Nadolol or propranolol (or carvedilol).","Nadolol ou propranolol."],["96dajimuv","Which beta-blocker is used in thyroid storm?","Propranolol (also inhibits T4 to T3 conversion).","Propranolol."],["j6so1g7wz","Which beta-blocker is very short acting for SVT and aortic dissection?","Esmolol.","Esmolol."],["10wfpzhjm","What is the mechanism of ganglionic blockers?","Nicotinic Nn receptor antagonists (hexamethonium, mecamylamine) blocking both sympathetic and parasympathetic ganglia; used historically; prevents baroreceptor reflex.","Bloqueiam gânglios autonômicos."],["1qnsagmev","What is the effect of norepinephrine on heart rate in the presence vs absence of ganglionic blockade?","Normally causes reflex bradycardia (baroreceptor); with ganglionic blockade or atropine, HR increases (direct beta1).","Bradicardia reflexa desaparece com bloqueio ganglionar."],["vkjrah1n5","What is the effect of epinephrine reversal by an alpha-blocker?","With alpha-blockade, epinephrine causes hypotension (unopposed beta2 vasodilation).","Reversão da adrenalina."],["168vrrk1l","What is the effect of isoproterenol on blood pressure?","Increases systolic slightly, decreases diastolic (beta2 vasodilation), decreases MAP, increases HR.","Reduz a diastólica."],["175yetry4","What is the effect of phenylephrine on heart rate?","Reflex bradycardia due to increased BP.","Bradicardia reflexa."],["1un9o83yb","What drug class is used to treat hypotension in septic shock?","Vasopressors: norepinephrine first line, vasopressin second.","Noradrenalina."],["wz9wdlto0","What drug is first line in anaphylaxis?","IM epinephrine.","Adrenalina intramuscular."],["shxsqm1yz","What drug is used for cardiac arrest (asystole/PEA)?","Epinephrine.","Adrenalina."],["1ccm8kc1t","What drug is used for symptomatic bradycardia?","Atropine; then epinephrine or dopamine infusion, or pacing.","Atropina."],["pc99r61lv","What drug class is used for urge incontinence?","Antimuscarinics (oxybutynin) or beta3 agonists (mirabegron).","Antimuscarínicos."],["1x9ng4y19","What drug is used for urinary retention without obstruction?","Bethanechol.","Betanecol."],["d2zj6x31c","What drug is used for xerostomia in Sjögren?","Pilocarpine or cevimeline.","Pilocarpina."],["1kzn815in","What drug is used for myasthenia gravis symptomatic treatment?","Pyridostigmine.","Piridostigmina."],["170wi8irm","What drug reverses nondepolarizing neuromuscular blockade?","Neostigmine with glycopyrrolate (or sugammadex).","Neostigmina com glicopirrolato."],["nlfh9t1xg","Why is glycopyrrolate given with neostigmine?","Prevents muscarinic side effects (bradycardia, secretions).","Bloqueia efeitos muscarínicos."],["7mtmdwiiv","What is the treatment of anticholinergic toxicity?","Supportive care; physostigmine for severe cases.","Suporte; fisostigmina."],["1i73sdpqm","What is the treatment of cocaine-induced hypertension and chest pain?","Benzodiazepines, nitrates, CCBs, phentolamine; avoid beta-blockers (classic teaching).","Benzodiazepínicos e nitratos."],["15y2e7qc8","What is the mechanism of reserpine's adverse effect of depression?","Depletion of monoamines (NE, serotonin, dopamine) in the CNS.","Depleção de monoaminas."],["y7qt0l1d8","What drug is used to diagnose pheochromocytoma pharmacologically (historical)?","Clonidine suppression test (no suppression of catecholamines in pheochromocytoma).","Teste da clonidina."],["qo11aglxd","Which receptor is responsible for epinephrine's bronchodilation?","Beta2.","Beta2."],["1hxd3bf1d","Which receptor causes mydriasis via the radial muscle?","Alpha1.","Alfa-1."],["jczc5k9jj","Which receptor mediates ejaculation (emission)?","Alpha1 (sympathetic).","Alfa-1."],["1wmey5g1y","Which receptor mediates erection?","Parasympathetic (M3 with NO).","Parassimpático."],["1xj1thma3","Which receptor decreases insulin secretion?","Alpha2.","Alfa-2."],["1h42cof3t","Which receptor increases renin release?","Beta1.","Beta-1."],["13dkagnwq","Which receptor mediates bladder detrusor contraction?","M3.","M3."],["as1i4dmsw","Which receptor mediates sweating?","Muscarinic (M3, sympathetic cholinergic).","Muscarínico."],["4qk5yaie7","Which receptor mediates uterine relaxation?","Beta2.","Beta-2."]]},{"name":"Autonomic Drugs (Part 2)","cards":[["1xc33g21e","What is the classic autonomic drug identification setup in USMLE?","Changes in BP and HR before and after an antagonist or reflex blocker identify the drug (e.g., epinephrine reversal with alpha-blocker).","Identificar droga por pressão e frequência."],["1hmcx401n","What happens to BP and HR with low-dose epinephrine?","Increased systolic, decreased diastolic (beta2 vasodilation), increased HR (beta1), MAP roughly unchanged.","Sistólica sobe, diastólica cai."],["1b6lgiio5","What happens to BP and HR with high-dose epinephrine?","Alpha1 vasoconstriction dominates: increased systolic and diastolic, increased MAP; HR may fall reflexively.","Pressão sobe muito."],["1ntmk9jo3","What happens to BP and HR with norepinephrine?","Increased systolic, diastolic, and MAP; reflex bradycardia.","Pressão sobe; bradicardia reflexa."],["1agk6up5j","What happens with norepinephrine after atropine?","Tachycardia (beta1 unmasked) because reflex bradycardia is blocked.","Taquicardia após atropina."],["1gnn0sf9e","What drug decreases BP and increases HR, and is blocked by propranolol?","Isoproterenol.","Isoproterenol."],["nunumk5kt","What drug increases BP and decreases HR, blocked by prazosin?","Phenylephrine (or norepinephrine).","Fenilefrina."],["1yxikqdnp","What drug increases HR without much BP change, effects blocked by a beta1 blocker?","Dobutamine (beta1 > beta2).","Dobutamina."],["oqgrpg1ny","What is tachyphylaxis of indirect sympathomimetics?","Repeated doses deplete NE stores, reducing effect (ephedrine).","Esgota a noradrenalina."],["p4n9znntl","Why does an alpha-blocker cause reflex tachycardia?","Vasodilation lowers BP, triggering baroreceptor-mediated sympathetic activation.","Hipotensão gera taquicardia reflexa."],["4ipb591dk","What is the mechanism of mydriasis from phenylephrine vs tropicamide?","Phenylephrine: alpha1 contracts radial (dilator) muscle without cycloplegia. Tropicamide: blocks M3 on sphincter, causing mydriasis and cycloplegia.","Alfa-1 versus antimuscarínico."],["1fq3vbagp","Which drugs lower intraocular pressure by decreasing aqueous production?","Beta-blockers (timolol), alpha2 agonists (brimonidine, apraclonidine), carbonic anhydrase inhibitors.","Timolol, brimonidina, acetazolamida."],["1l3io2e1g","Which drugs lower intraocular pressure by increasing outflow?","Prostaglandins (latanoprost), cholinomimetics (pilocarpine, carbachol, echothiophate), epinephrine.","Latanoprosta e pilocarpina."],["1kk9hmvwr","Why is epinephrine contraindicated in closed-angle glaucoma?","Mydriasis can worsen angle closure.","Midríase piora o fechamento."],["o7hi8cu5c","Adverse effect of brimonidine?","Allergic conjunctivitis, ocular pruritus; avoid in infants (CNS depression).","Conjuntivite alérgica."],["qciz5ingf","Adverse effects of timolol eye drops?","Systemic beta-blockade: bradycardia, bronchospasm.","Efeitos sistêmicos."],["1q0fh9w1q","What is the treatment of BPH with hypertension?","Alpha1 blockers (doxazosin, terazosin).","Doxazosina."],["o6f5l3ktp","What is the mechanism of tamsulosin's uroselectivity?","Selective for alpha1A receptors in the prostate.","Seletivo para alfa-1A."],["1y66ll11j","What is the treatment of BPH to shrink prostate size?","5-alpha-reductase inhibitors (finasteride, dutasteride).","Finasterida."],["41tnq0g8z","What drug is used for erectile dysfunction and BPH symptoms?","Tadalafil (PDE5 inhibitor).","Tadalafila."],["43kvkif1d","What is the mechanism of PDE5 inhibitors?","Inhibit PDE5, increasing cGMP, smooth muscle relaxation in corpus cavernosum and pulmonary vasculature.","Aumentam GMPc."],["6i647q1qh","Adverse effects of PDE5 inhibitors?","Headache, flushing, dyspepsia, cyanopia (blue-tinged vision, sildenafil), hypotension with nitrates, NAION.","Visão azulada; hipotensão com nitratos."],["abafng1il","What is the mechanism of nicotine?","Agonist at nicotinic receptors (ganglia, adrenal medulla, NMJ, CNS); low doses stimulate, high doses block.","Agonista nicotínico."],["9jmpwv150","What is varenicline's mechanism?","Partial agonist at alpha4-beta2 nicotinic receptors; smoking cessation; may cause vivid dreams, nausea.","Agonista parcial nicotínico."],["3crhym2hc","What is bupropion's role in smoking cessation?","NE and dopamine reuptake inhibitor; contraindicated in seizure disorders, bulimia, anorexia.","Inibe recaptação; contraindicado em convulsões."],["11fbem71o","What drugs treat hypotension from spinal anesthesia?","Phenylephrine or ephedrine.","Fenilefrina ou efedrina."],["qwb8v01mj","Which drug causes vasodilation via D1 receptors in the kidney?","Fenoldopam (and low-dose dopamine).","Fenoldopam."],["1eh33a51k","Which drug is used for orthostatic hypotension (alpha1 agonist prodrug)?","Midodrine.","Midodrina."],["oh61otz9q","Adverse effect of midodrine?","Supine hypertension, piloerection, urinary retention.","Hipertensão deitado."],["vqre1fufl","Which drug is used for orthostatic hypotension by volume expansion?","Fludrocortisone.","Fludrocortisona."],["sgd9655uv","Which drug is used for neurogenic orthostatic hypotension by increasing NE?","Droxidopa (NE prodrug).","Droxidopa."],["iwrwig147","What is the mechanism of cholinergic crisis vs myasthenic crisis distinction?","Cholinergic crisis: excess AChE inhibitor with SLUDGE signs; myasthenic crisis improves with more AChE inhibitor; distinguished clinically (edrophonium historically).","Excesso de medicação versus doença."],["83vwrl13k","What is the autonomic effect of TCAs?","Anticholinergic (dry mouth, urinary retention), alpha1 blockade (orthostatic hypotension), antihistamine (sedation).","Anticolinérgico e alfa-bloqueio."],["1wf3ajgzn","What is the autonomic effect of first-generation antihistamines?","Anticholinergic effects and sedation.","Anticolinérgico e sedação."],["9ul3c6ry6","What is the autonomic effect of low-potency antipsychotics?","Anticholinergic, alpha1 blockade, antihistamine effects.","Anticolinérgico e hipotensão."],["kyaerv18m","What is the autonomic effect of opioids on the pupil?","Miosis (parasympathetic via Edinger-Westphal).","Miose."],["1fnppry1b","What is the autonomic effect of sympathomimetic toxicity?","Tachycardia, hypertension, mydriasis, diaphoresis, hyperthermia, agitation (sweaty, unlike anticholinergic dry skin).","Taquicardia, midríase e suor."],["ft2gzo181","How do you distinguish sympathomimetic from anticholinergic toxicity?","Both cause tachycardia, mydriasis, hyperthermia; sympathomimetic: diaphoresis and bowel sounds present. Anticholinergic: dry skin, absent bowel sounds, urinary retention.","Suor versus pele seca."],["iwq7u654j","What is the autonomic effect of cholinergic toxicity on the heart?","Bradycardia (M2).","Bradicardia."],["be1izsjsy","What is the autonomic effect of beta-blocker toxicity?","Bradycardia, hypotension, hypoglycemia, bronchospasm.","Bradicardia e hipoglicemia."],["ijrm2w1rp","What is the autonomic effect of calcium channel blocker toxicity?","Bradycardia, hypotension, hyperglycemia (decreased insulin release).","Bradicardia e hiperglicemia."],["1y34jijtt","What is the treatment for calcium channel blocker overdose?","IV calcium, high-dose insulin with glucose, vasopressors, lipid emulsion.","Cálcio e insulina em altas doses."],["6b4caly24","What is the effect of nicotinic Nm receptor blockade?","Skeletal muscle paralysis (neuromuscular blockers).","Paralisia muscular."],["a1742m1tw","What is the effect of nicotinic Nn receptor blockade?","Autonomic ganglionic blockade (hypotension, loss of reflexes).","Bloqueio ganglionar."],["gg35hw1py","What is the role of atropine in organophosphate poisoning regarding muscle weakness?","Atropine does not reverse nicotinic effects (muscle paralysis); pralidoxime does.","Atropina não reverte a paralisia."],["1c2sixb1y","What is the role of physostigmine vs neostigmine in CNS effects?","Physostigmine is a tertiary amine that crosses the BBB; neostigmine is quaternary and does not.","Fisostigmina atravessa a barreira."],["co4vc0keq","What drug is used to diagnose asthma via bronchial hyperreactivity?","Methacholine.","Metacolina."],["1ij0zwchx","What drug is used in Alzheimer disease that is also a butyrylcholinesterase inhibitor?","Rivastigmine.","Rivastigmina."],["5b4to11a7","Which antihypertensive is preferred for hypertensive emergency with pheochromocytoma?","Phentolamine (or nitroprusside, nicardipine).","Fentolamina."],["uj3162hfg","Which beta-blockers have intrinsic sympathomimetic activity?","Pindolol and acebutolol (partial agonists); avoid after MI and in angina.","Pindolol e acebutolol."],["zrd4togqr","Which beta-blocker is preferred in pregnancy for hypertension?","Labetalol.","Labetalol."],["mg06my16f","Which beta-blocker is preferred in hepatic cirrhosis for varices?","Nonselective (propranolol, nadolol, carvedilol).","Não seletivo."],["1scqbriqk","Which beta-blocker is used for performance anxiety?","Propranolol.","Propranolol."],["heh9cyebu","Which beta-blocker is renally cleared and requires dose adjustment?","Atenolol and nadolol.","Atenolol e nadolol."],["1bkypyhmj","Which beta-blocker is lipophilic and crosses the BBB?","Propranolol (more CNS effects).","Propranolol."],["jmhhzl1dt","What is the mechanism of labetalol?","Nonselective beta-blocker with alpha1 blockade.","Bloqueia beta e alfa-1."],["xrqyrtegz","What are the effects of alpha2 agonists in the eye?","Decrease aqueous humor production (brimonidine).","Reduzem o humor aquoso."],["vlv1nt14w","What is the mechanism of oxymetazoline?","Alpha agonist nasal decongestant; rebound congestion with prolonged use (rhinitis medicamentosa).","Descongestionante; efeito rebote."],["ekgihrked","Why are decongestants (pseudoephedrine) cautioned in hypertension and BPH?","Alpha agonism raises BP and causes urinary retention.","Sobem pressão e retêm urina."],["smx5al18g","What is the effect of dopamine at high doses?","Alpha1 vasoconstriction (increased SVR).","Vasoconstrição."],["s78jns1ig","Which drug is used for heart failure with cardiogenic shock and low BP?","Norepinephrine (with dobutamine).","Noradrenalina."],["16agnwz9a","What is the mechanism of droxidopa?","Synthetic precursor converted to norepinephrine by DOPA decarboxylase.","Precursor da noradrenalina."],["1cwn6jct8","What drug blocks catecholamine synthesis and treats pheochromocytoma symptoms?","Metyrosine (tyrosine hydroxylase inhibitor).","Metirosina."],["1mupz4cs3","Which drug is a peripheral DOPA decarboxylase inhibitor?","Carbidopa.","Carbidopa."],["5njmlm99e","Which drug inhibits COMT to prolong levodopa?","Entacapone.","Entacapona."],["onh4md1t4","Which drug inhibits MAO-B?","Selegiline, rasagiline.","Selegilina e rasagilina."],["1uj3su6h6","What is the effect of MAO inhibitors on catecholamines?","Increase levels of NE, serotonin, dopamine by preventing breakdown.","Aumentam monoaminas."],["11ur74q2b","What is the hypertensive crisis risk with MAOIs?","Interaction with tyramine, sympathomimetics, meperidine, SSRIs (serotonin syndrome).","Tiramina e simpaticomiméticos."],["1yz2to7sj","What is the mechanism of botulinum toxin in autonomic disorders?","Blocks ACh release; treats hyperhidrosis, achalasia, overactive bladder, sialorrhea.","Bloqueia acetilcolina."],["cilg5yedk","What autonomic receptor is targeted to treat achalasia pharmacologically?","Smooth muscle relaxation with nitrates or CCBs; botulinum toxin blocks ACh.","Nitratos ou toxina botulínica."],["dtna8djtm","Which drug is used to treat hyperhidrosis topically?","Aluminum chloride, topical glycopyrronium; botulinum toxin injections.","Cloreto de alumínio e toxina botulínica."],["recok21f7","Which drug treats sialorrhea?","Glycopyrrolate or botulinum toxin.","Glicopirrolato."],["941dxvyj4","What is the effect of muscarinic agonists on the heart?","Decreased HR (M2) and AV conduction.","Reduzem a frequência."],["1ejv42prr","What is the effect of muscarinic antagonists on GI motility?","Decrease motility and secretions (constipation).","Reduzem a motilidade."],["18c4lppbx","What is the effect of beta2 agonists on potassium?","Shift K+ into cells (used to treat hyperkalemia).","Potássio entra nas células."],["1yxfpxuyz","What is the effect of beta2 agonists on glucose?","Increase glycogenolysis and blood glucose.","Aumentam a glicose."],["btazgff1w","What is the effect of beta2 agonists on the uterus?","Relaxation (tocolysis historically).","Relaxam o útero."],["1kpqtg211","What is the effect of alpha1 agonists on the bladder?","Contraction of internal urethral sphincter (urinary retention).","Contraem o esfíncter."],["nih4ndp2m","What is the effect of alpha1 antagonists on the bladder?","Relax internal sphincter and prostate smooth muscle (improve urine flow).","Relaxam o esfíncter."],["qa98eq9ak","What is the effect of M3 antagonists on the bladder?","Relax detrusor (decrease urge incontinence).","Relaxam o detrusor."],["1lia35kg1","What drug class causes orthostatic hypotension in elderly men taking it for BPH?","Alpha1 blockers.","Alfa-bloqueadores."],["1dzx00aw8","What is the treatment of hyperkalemia using an autonomic drug?","Nebulized albuterol (beta2 agonist) shifts K+ into cells.","Salbutamol nebulizado."],["1t4yeyvj0","What is the effect of vagal stimulation on SVT?","Slows AV nodal conduction, may terminate reentrant SVT (carotid massage, Valsalva).","Manobras vagais."],["1ja8seavl","What autonomic receptor mediates salivary secretion?","M3 (parasympathetic) and beta1/alpha1 (sympathetic, thick saliva).","M3."],["6vbe411ok","What autonomic receptor mediates lipolysis?","Beta1 and beta3 (and beta2).","Beta-1 e beta-3."],["bf7pey1h2","What autonomic receptor mediates platelet aggregation?","Alpha2.","Alfa-2."],["zfncez1dq","What is the mechanism of yohimbine?","Alpha2 antagonist (increases sympathetic outflow).","Antagonista alfa-2."],["a0du363kc","What is the autonomic mechanism of clonidine's sedation?","Central alpha2 agonism reduces locus coeruleus activity.","Reduz o locus ceruleus."],["1qcgukeld","What is the treatment of opioid withdrawal autonomic symptoms?","Clonidine or lofexidine (alpha2 agonists), buprenorphine, methadone.","Clonidina ou lofexidina."],["14vidry1q","What drug is a selective alpha1A blocker used for kidney stone passage?","Tamsulosin (medical expulsive therapy).","Tansulosina."],["b431id1rz","Which drug is a direct-acting vasodilator via K+ channel opening?","Minoxidil.","Minoxidil."],["t0i4ub1rt","Which drug is used for acute angle-closure glaucoma to constrict pupil?","Pilocarpine.","Pilocarpina."],["4zdfve1pf","What drugs cause miosis and are used for glaucoma?","Pilocarpine, carbachol, echothiophate.","Pilocarpina e carbacol."],["111ppomjm","What is the effect of nicotinic receptor activation at the adrenal medulla?","Release of epinephrine (and norepinephrine).","Liberação de adrenalina."],["ji17axf9e","Which autonomic drug can cause hyperthermia by blocking sweating?","Atropine (anticholinergic).","Atropina."],["jedug98v7","What is the effect of muscarinic agonists on vessels?","Vasodilation via endothelial NO release (M3).","Vasodilatação por óxido nítrico."],["hzywdqmhx","Which drug reverses atropine poisoning?","Physostigmine.","Fisostigmina."],["u34a5q1jm","Which receptor mediates bronchial smooth muscle contraction?","M3.","M3."],["bn1xtuqw9","What is the autonomic effect of anticholinergics on bronchi?","Bronchodilation and decreased secretions (ipratropium).","Broncodilatação."],["7fogjs1id","Why may glycopyrrolate be added to pyridostigmine in myasthenia gravis?","To reduce muscarinic side effects (diarrhea, salivation) without blocking nicotinic benefit at the neuromuscular junction.","Reduz efeitos muscarínicos."],["1ceb0ba10","Which receptor mediates vasoconstriction in the skin and splanchnic beds?","Alpha1.","Alfa-1."],["pk93q01wy","What is the effect of beta1 blockade on renin?","Decreases renin release, lowering BP.","Reduz renina."]]},{"name":"Drug Naming","cards":[["1hx09my3a","What drug class ends in -azepam or -azolam?","Benzodiazepines (diazepam, alprazolam).","Benzodiazepínicos."],["1lco4sv33","What drug class ends in -barbital?","Barbiturates (phenobarbital).","Barbitúricos."],["sg2scs3qq","What drug class ends in -caine?","Local anesthetics (lidocaine).","Anestésicos locais."],["1jum1hn7p","What drug class ends in -flurane?","Inhaled anesthetics (sevoflurane).","Anestésicos inalatórios."],["c3s6p11pb","What drug class ends in -peridol?","Butyrophenone typical antipsychotics (haloperidol).","Antipsicóticos butirofenonas."],["1x321fq1a","What drug class ends in -apine or -idone?","Atypical antipsychotics (quetiapine, risperidone).","Antipsicóticos atípicos."],["1b9wtc8dh","What drug class ends in -triptan?","5-HT1B/1D agonists for migraine (sumatriptan).","Triptanos."],["o20401xro","What drug class ends in -triptyline?","Tricyclic antidepressants (amitriptyline).","Tricíclicos."],["1lo5nhz19","What drug class ends in -oxetine or -aline?","SSRIs (fluoxetine, sertraline).","Inibidores seletivos de serotonina."],["yidf0srrj","What drug class ends in -giline?","MAO-B inhibitors (selegiline).","Inibidores da MAO-B."],["1l1yvakq6","What drug class ends in -olol?","Beta-blockers (propranolol).","Betabloqueadores."],["1l1z1hzq6","What drug class ends in -osin?","Alpha1 blockers (prazosin).","Bloqueadores alfa-1."],["nu58181qk","What drug class ends in -terol?","Beta2 agonists (albuterol, salmeterol).","Agonistas beta-2."],["1chby6cc3","What drug class ends in -tropium?","Muscarinic antagonists (ipratropium, tiotropium).","Antimuscarínicos inalatórios."],["mefvh7ey9","What drug class ends in -curium or -curonium?","Nondepolarizing neuromuscular blockers (atracurium, vecuronium).","Bloqueadores neuromusculares."],["lk6kq1e81","What drug class ends in -stigmine?","AChE inhibitors (neostigmine).","Anticolinesterásicos."],["1kmbei3pi","What drug class ends in -pril?","ACE inhibitors (lisinopril).","IECA."],["suidnb1u2","What drug class ends in -sartan?","Angiotensin II receptor blockers (losartan).","BRA."],["1y57vgz1x","What drug class ends in -dipine?","Dihydropyridine calcium channel blockers (amlodipine).","Bloqueadores de cálcio di-hidropiridínicos."],["163n8op8d","What drug class ends in -statin?","HMG-CoA reductase inhibitors (atorvastatin).","Estatinas."],["tfjig3190","What drug class ends in -fibrate?","PPAR-alpha activators (fenofibrate).","Fibratos."],["lbrfzc1o1","What drug class ends in -parin?","Low-molecular-weight heparins (enoxaparin).","Heparinas de baixo peso."],["qhte481t7","What drug class ends in -xaban?","Direct factor Xa inhibitors (apixaban, rivaroxaban).","Inibidores do fator Xa."],["t6lqv71uh","What drug class ends in -gatran?","Direct thrombin inhibitors (dabigatran).","Inibidores diretos da trombina."],["10bnbsm6w","What drug class ends in -teplase?","Thrombolytics (alteplase).","Trombolíticos."],["1kwch4gq0","What drug class ends in -grel?","ADP (P2Y12) receptor inhibitors (clopidogrel).","Inibidores do P2Y12."],["1s4c0b7ue","What drug class ends in -prazole?","Proton pump inhibitors (omeprazole).","Inibidores da bomba de prótons."],["crn1nbbvj","What drug class ends in -tidine?","H2 blockers (famotidine).","Bloqueadores H2."],["ve9d251wo","What drug class ends in -setron?","5-HT3 antagonists (ondansetron).","Antagonistas 5-HT3."],["yejah11gg","What drug class ends in -glitazone?","PPAR-gamma activators (pioglitazone).","Glitazonas."],["9jvrfxwnq","What drug class ends in -gliptin?","DPP-4 inhibitors (sitagliptin).","Gliptinas."],["5s9u2e1l5","What drug class ends in -gliflozin?","SGLT2 inhibitors (empagliflozin).","Glifozinas."],["62j4w8gqp","What drug class ends in -glutide or -enatide?","GLP-1 receptor agonists (semaglutide, exenatide).","Agonistas de GLP-1."],["1mtr5ormo","What drug class ends in -dronate?","Bisphosphonates (alendronate).","Bisfosfonatos."],["wfmjn01nn","What drug class ends in -sone or -olone?","Glucocorticoids (prednisone, prednisolone).","Corticoides."],["k9efpd1lj","What drug class ends in -cillin?","Penicillins (amoxicillin).","Penicilinas."],["dt9vu0ert","What drug class starts with cef- or ceph-?","Cephalosporins (ceftriaxone).","Cefalosporinas."],["lebrtr1o4","What drug class ends in -penem?","Carbapenems (meropenem).","Carbapenêmicos."],["1gxhi7z7i","What drug class ends in -mycin (aminoglycosides) or -micin?","Aminoglycosides (gentamicin, tobramycin) and some others (erythromycin is a macrolide).","Aminoglicosídeos e outros."],["18l6mwr1t","What drug class ends in -cycline?","Tetracyclines (doxycycline).","Tetraciclinas."],["10pjt043c","What drug class ends in -floxacin?","Fluoroquinolones (ciprofloxacin).","Fluoroquinolonas."],["s4bovx164","What drug class ends in -thromycin?","Macrolides (azithromycin, clarithromycin).","Macrolídeos."],["yvnx4j1ba","What drug class ends in -conazole?","Azole antifungals (fluconazole).","Antifúngicos azólicos."],["1x43jw1z5","What drug class ends in -fungin?","Echinocandins (caspofungin).","Equinocandinas."],["151051p1w","What drug class ends in -vir (with -navir)?","Protease inhibitors (ritonavir).","Inibidores de protease."],["gpcero47r","What drug class ends in -tegravir?","Integrase inhibitors (dolutegravir).","Inibidores de integrase."],["y58cln100","What drug class ends in -ciclovir?","Guanosine analogs for herpesviruses (acyclovir, ganciclovir).","Antivirais do herpes."],["1hlqj0k5g","What drug class ends in -amivir?","Neuraminidase inhibitors (oseltamivir, zanamivir).","Inibidores da neuraminidase."],["rn759y2xr","What drug class ends in -buvir?","HCV NS5B polymerase inhibitors (sofosbuvir).","Inibidores da polimerase do HCV."],["qym7o31ys","What drug class ends in -asvir?","HCV NS5A inhibitors (ledipasvir).","Inibidores de NS5A."],["460m5izqo","What drug class ends in -previr?","HCV NS3/4A protease inhibitors (glecaprevir).","Inibidores de protease do HCV."],["1f8frpe78","What drug class ends in -mab?","Monoclonal antibodies (-ximab chimeric, -zumab humanized, -umab human).","Anticorpos monoclonais."],["1ktsp1qpy","What drug class ends in -cept?","Receptor fusion proteins (etanercept, abatacept).","Proteínas de fusão."],["o20gfo1qs","What drug class ends in -tinib?","Tyrosine kinase inhibitors (imatinib).","Inibidores de tirosina quinase."],["mksgf31wt","What drug class ends in -zomib?","Proteasome inhibitors (bortezomib).","Inibidores do proteassoma."],["14pb5ms1k","What drug class ends in -rubicin?","Anthracyclines (doxorubicin).","Antraciclinas."],["aui3m1ylb","What drug class ends in -platin?","Platinum compounds (cisplatin).","Platinas."],["nx92y01qn","What drug class ends in -taxel?","Taxanes (paclitaxel).","Taxanos."],["ntrtht1qj","What drug class ends in -tecan?","Topoisomerase I inhibitors (irinotecan).","Inibidores da topoisomerase I."],["y9c6lm1ya","What drug class ends in -dafil?","PDE5 inhibitors (sildenafil, tadalafil).","Inibidores da PDE5."]]},{"name":"Pharmacodynamics","cards":[["zvdhqwuge","What is bioavailability (F)?","Fraction of administered drug reaching systemic circulation unchanged; IV = 100%; oral less due to incomplete absorption and first-pass metabolism.","Fração que chega à circulação."],["16oie6pmk","What is volume of distribution?","Theoretical volume occupied by total drug amount at the plasma concentration: Vd = amount of drug / plasma concentration.","Volume aparente de distribuição."],["1pplzeb1h","What does a low Vd indicate?","Drug stays in blood: large, charged, or highly plasma protein-bound molecules.","Fica no sangue."],["1ykmd0pix","What does a high Vd indicate?","Drug distributes widely into tissues (lipophilic, small); e.g., amiodarone.","Vai para os tecidos."],["1xhtd5jx5","How do liver and kidney disease affect Vd?","Decrease plasma proteins (hypoalbuminemia), increasing Vd of protein-bound drugs.","Albumina baixa aumenta o Vd."],["osi5ru5ui","What is clearance?","Volume of plasma cleared of drug per unit time: CL = rate of elimination / plasma concentration = Vd x Ke.","Volume de plasma depurado por tempo."],["609v6qsr5","What is half-life?","Time to reduce plasma concentration by 50%: t1/2 = 0.7 x Vd / CL.","Tempo para cair pela metade."],["r4hhzpu2x","How many half-lives to reach steady state?","About 4-5 half-lives (94-97%).","Quatro a cinco meias-vidas."],["nt48o6119","What is the loading dose formula?","Loading dose = (Cp x Vd) / F.","Dose de ataque."],["wd0671s8l","What is the maintenance dose formula?","Maintenance dose = (Cp x CL x dosing interval) / F.","Dose de manutenção."],["ugvkm3yz1","How does renal or liver disease affect loading and maintenance doses?","Maintenance dose decreases; loading dose usually unchanged.","Reduz a manutenção."],["1v82aqkaw","What is zero-order elimination?","Constant amount eliminated per unit time regardless of concentration (PEA: phenytoin, ethanol, aspirin at high doses).","Quantidade constante; fenitoína, etanol, aspirina."],["1q4h7t0hw","What is first-order elimination?","Constant fraction eliminated per unit time, proportional to concentration (most drugs).","Fração constante."],["woetfu1vz","How does urine pH affect drug elimination?","Ionized species are trapped in urine and cleared faster; weak acids cleared with alkaline urine, weak bases with acidic urine.","Forma ionizada é excretada."],["gejchz1kk","Which drugs are weak acids and how is overdose treated?","Phenobarbital, methotrexate, aspirin: treat with bicarbonate to alkalinize urine.","Ácidos fracos; alcalinizar urina."],["2fi1bx1k9","Which drugs are weak bases and how is overdose treated?","TCAs, amphetamines: historically acidification (ammonium chloride); bicarbonate for TCA cardiac toxicity.","Bases fracas."],["354o871k5","What is phase I metabolism?","Reduction, oxidation, hydrolysis by CYP450; yields slightly polar metabolites; geriatric patients lose phase I first.","Oxidação pelo CYP450."],["ffgk5q1ff","What is phase II metabolism?","Conjugation (glucuronidation, acetylation, sulfation) yielding very polar inactive metabolites excreted by kidneys; slow acetylators have more side effects.","Conjugação."],["1vmv70519","Which drugs are affected by slow acetylators?","Isoniazid, hydralazine, procainamide, sulfonamides (drug-induced lupus, neuropathy).","Isoniazida, hidralazina, procainamida."],["1298k3iy6","What is efficacy?","Maximal effect a drug can produce (Vmax); partial agonists have lower efficacy than full agonists.","Efeito máximo."],["d4j7ow1bm","What is potency?","Amount of drug needed for a given effect (EC50); more potent drugs have lower EC50 (left shift).","Dose necessária para o efeito."],["11ausd01q","What does a competitive antagonist do to the dose-response curve?","Shifts curve right (decreased potency), no change in efficacy; can be overcome by more agonist.","Desloca à direita."],["j5566z1su","What does a noncompetitive antagonist do to the dose-response curve?","Shifts curve down (decreased efficacy); cannot be overcome by more agonist.","Reduz o efeito máximo."],["1kd5bul1o","What does a partial agonist do?","Acts at the same site as a full agonist with lower maximal efficacy; potency may be higher or lower (e.g., buprenorphine, aripiprazole).","Eficácia menor."],["1egfirgbd","What is an inverse agonist?","Binds receptor and produces the opposite effect of an agonist (reduces constitutive activity).","Efeito oposto ao agonista."],["1uotba1p7","What is the therapeutic index?","TD50 / ED50; measures safety; higher index is safer.","Índice terapêutico; maior é mais seguro."],["r1i3f9170","Which drugs have a low therapeutic index?","Warfarin, theophylline, digoxin, antiepileptics, lithium, aminoglycosides, vancomycin (monitor levels).","Varfarina, digoxina, lítio, aminoglicosídeos."],["rx02kr1qq","What is the therapeutic window?","Range between minimum effective dose and minimum toxic dose.","Janela entre efeito e toxicidade."],["1oz3fkz1u","What is tachyphylaxis?","Rapid decrease in response after repeated doses (nitrates, ephedrine).","Perda rápida de efeito."],["1px0w4j15","What is tolerance?","Need for increasing doses to achieve the same effect over time.","Precisa de mais dose."],["1ntxohpg2","What is an additive drug interaction?","Effect of A + B equals sum of individual effects.","Efeito soma."],["1tfmvqk1x","What is a permissive drug interaction?","Presence of A is required for the full effect of B (cortisol on catecholamines).","Um permite o efeito do outro."],["17jp10l1k","What is a synergistic drug interaction?","Effect of A + B is greater than the sum of individual effects.","Efeito maior que a soma."],["slm8z51dp","What is a potentiation interaction?","A has no effect alone but enhances B.","Um potencializa o outro."],["o3ff8ijjf","What is the first-pass effect?","Metabolism of an orally administered drug in the gut wall and liver before systemic circulation (e.g., nitroglycerin, propranolol, morphine).","Metabolismo de primeira passagem."],["1rxh1m13a","Which routes bypass first-pass metabolism?","IV, sublingual, transdermal, rectal (partially), inhalational.","Venosa, sublingual, transdérmica."],["1ub4gkik6","What is a prodrug?","Inactive drug converted to active form in the body (e.g., clopidogrel, codeine, enalapril, levodopa, cyclophosphamide, azathioprine).","Droga ativada no organismo."],["1ovalr2bz","Why do CYP2D6 ultrarapid metabolizers have codeine toxicity?","Rapid conversion of codeine to morphine causing respiratory depression.","Convertem codeína em morfina rápido."],["14ma79i13","Why does CYP2C19 poor metabolism affect clopidogrel?","Reduced activation of the prodrug, decreasing antiplatelet effect.","Menos ativação do clopidogrel."],["tezacr1hk","Which genetic variant increases warfarin sensitivity?","CYP2C9 and VKORC1 variants (lower dose required).","CYP2C9 e VKORC1."],["ok3ebhvh3","What is TPMT testing used for?","Predicting severe myelosuppression with azathioprine and 6-MP.","Prever toxicidade da azatioprina."],["13wa5fpmn","What is DPD deficiency testing used for?","Predicting severe 5-FU and capecitabine toxicity.","Toxicidade do 5-FU."],["1g0gglj5l","What is UGT1A1 testing used for?","Predicting irinotecan toxicity (Gilbert-like polymorphism).","Toxicidade do irinotecano."],["1j0dvoshe","Which drugs are CYP450 inducers?","Chronic alcohol, St. John's wort, phenytoin, phenobarbital, nevirapine, rifampin, griseofulvin, carbamazepine (Chronic alcoholics Steal Phen-Phen and Never Refuse Greasy Carbs).","Álcool crônico, erva-de-são-joão, fenitoína, rifampicina, carbamazepina."],["445hl61xl","Which drugs are CYP450 inhibitors?","Sodium valproate, isoniazid, cimetidine, ketoconazole/azoles, acute alcohol, chloramphenicol, erythromycin/clarithromycin, sulfonamides, ciprofloxacin, omeprazole, amiodarone, ritonavir, grapefruit juice (SICK FACES.COM).","Valproato, isoniazida, cimetidina, azóis, macrolídeos."],["1cbrw6arg","Which drugs are common CYP450 substrates?","Anti-epileptics, theophylline, warfarin, OCPs (Always Think When Outdoors).","Antiepilépticos, teofilina, varfarina, anticoncepcionais."],["1umsxic18","What happens to warfarin's effect with a CYP inducer?","Decreased INR (risk of thrombosis).","INR cai."],["1huz0vq15","What happens to OCP efficacy with rifampin?","Decreased efficacy (unintended pregnancy).","Falha do anticoncepcional."],["iivsu4ary","What is the role of P-glycoprotein in drug interactions?","Efflux transporter; inhibitors (verapamil, amiodarone, quinidine) increase digoxin levels.","Inibidores aumentam a digoxina."],["1bes9ud12","What are the routes of drug administration with fastest onset?","IV and inhalation.","Venosa e inalatória."],["mxp9el14m","What is enterohepatic recirculation and its significance?","Drugs conjugated in the liver, excreted in bile, deconjugated by gut bacteria and reabsorbed, prolonging half-life (OCPs affected by antibiotics).","Recirculação prolonga a ação."],["1h6tgf1ji","What is the significance of plasma protein binding?","Only free drug is active; displacement (sulfonamides displacing warfarin) increases free drug.","Só a fração livre age."],["cqn7tcwzv","What are the receptor types: Gq?","H1, alpha1, V1, M1, M3 (HAVe 1 M&M): phospholipase C, IP3 and DAG, increased Ca2+.","Receptores Gq."],["cqn7rmwzv","What are the receptor types: Gs?","beta1, beta2, beta3, D1, H2, V2: adenylyl cyclase, increased cAMP.","Receptores Gs."],["cqn808wzv","What are the receptor types: Gi?","M2, alpha2, D2 (MAD 2s): inhibit adenylyl cyclase, decreased cAMP.","Receptores Gi."],["fb1us3syb","What is the effect of alpha1 receptors?","Vasoconstriction, mydriasis, urinary sphincter contraction, increased BP.","Vasoconstrição e midríase."],["owfovke07","What is the effect of alpha2 receptors?","Decreased sympathetic outflow and insulin release, decreased lipolysis, increased platelet aggregation, decreased aqueous humor.","Reduz descarga simpática."],["1a4quid14","What is the effect of beta1 receptors?","Increased HR, contractility, renin release, lipolysis.","Coração e renina."],["gd4nx21ek","What is the effect of beta2 receptors?","Vasodilation, bronchodilation, increased lipolysis, insulin release, glycogenolysis, uterine relaxation, aqueous humor production, cellular K+ uptake.","Broncodilatação e vasodilatação."],["1ystvaii9","What is the effect of M1 receptors?","CNS and enteric nervous system.","SNC e sistema nervoso entérico."],["15esz2h1v","What is the effect of M2 receptors?","Decreased heart rate and contractility of atria.","Reduz frequência cardíaca."],["1e2ke08zk","What is the effect of M3 receptors?","Increased exocrine gland secretions, gut peristalsis, bladder contraction, bronchoconstriction, miosis, accommodation, insulin release, endothelium-mediated vasodilation.","Secreções, peristalse, bexiga, broncoconstrição."],["tmi90j1ea","What is the effect of D1 receptors?","Relaxes renal vascular smooth muscle, activates direct pathway of striatum.","Vasodilatação renal."],["vewedc8nf","What is the effect of D2 receptors?","Modulates transmitter release, especially in brain; inhibits indirect pathway; inhibits prolactin.","Inibe prolactina."],["1rht4xbd4","What is the effect of H1 receptors?","Increased nasal and bronchial mucus, bronchoconstriction, increased vascular permeability, pruritus, pain.","Muco, broncoconstrição, coceira."],["1ta7aa416","What is the effect of H2 receptors?","Increased gastric acid secretion.","Secreção ácida."],["64e5khbwc","What is the effect of V1 receptors?","Vasoconstriction.","Vasoconstrição."],["1q7e5lelh","What is the effect of V2 receptors?","Increased water permeability in collecting ducts (aquaporin), increased factor VIII and vWF release.","Reabsorção de água."],["1hhj2v91f","What is a placebo vs nocebo effect?","Placebo: perceived benefit from inactive treatment. Nocebo: perceived adverse effects from inactive treatment due to negative expectations.","Efeito placebo e nocebo."],["q1lm88l9z","What is the definition of drug elimination half-life use in dosing?","Determines dosing interval and time to steady state.","Define intervalo de dose."],["7tkehz16j","What is the Henderson-Hasselbalch relevance to drug absorption?","Non-ionized drug crosses membranes; weak acids absorbed better in acidic stomach, weak bases in alkaline intestine.","Forma não ionizada é absorvida."],["1kmceahhg","What is the time to peak concentration influenced by?","Rate of absorption (route and formulation).","Velocidade de absorção."],["1bdk6vx13","What are the phases of drug development?","Preclinical, phase I (safety), II (efficacy), III (comparison), IV (postmarketing), then approval by FDA after phase III.","Fases do desenvolvimento."],["rf9lrfb12","What is an orphan drug?","Drug developed for rare diseases (<200,000 patients in US) with incentives.","Drogas para doenças raras."],["1ntxh8bpg","What is the FDA pregnancy labeling now?","Narrative risk summaries replacing letter categories (A, B, C, D, X).","Resumo de risco em texto."],["130s4ef6c","What is the significance of drug-induced QT prolongation?","Risk of torsades de pointes; avoid combining QT-prolonging drugs, correct electrolytes.","Risco de torsades."],["1j7jym9z4","What is a dose-response curve's slope significance?","Steep slope means small dose changes produce large effect changes.","Curva íngreme exige cuidado."],["1kh02vod6","What is the concept of spare receptors?","Maximal response achieved without occupying all receptors; increases sensitivity to agonists.","Receptores de reserva."],["5rc6w41re","What is receptor downregulation?","Decreased receptor number after chronic agonist exposure (tolerance).","Menos receptores com uso crônico."],["1030o5v1c","What is receptor upregulation?","Increased receptor number after chronic antagonist exposure (rebound tachycardia after beta-blocker withdrawal).","Mais receptores; rebote."],["4azeax12m","Why should beta-blockers not be stopped abruptly?","Receptor upregulation causes rebound tachycardia, hypertension, angina.","Rebote."],["1h1r3161y","Why should clonidine not be stopped abruptly?","Rebound hypertension.","Hipertensão rebote."],["1g455221r","Why should steroids not be stopped abruptly?","Adrenal insufficiency from HPA suppression.","Insuficiência adrenal."],["1oqfbjz1x","What are the effects of age on pharmacokinetics?","Decreased renal and hepatic clearance, increased body fat (higher Vd of lipophilic drugs), decreased albumin; start low, go slow.","Idosos eliminam menos."],["k17emn1vn","What are the Beers criteria?","List of potentially inappropriate medications in older adults (anticholinergics, benzodiazepines, long-acting sulfonylureas).","Medicamentos inadequados para idosos."],["1co5ik11i","Which drugs are associated with falls in the elderly?","Benzodiazepines, sedatives, antipsychotics, antihypertensives, anticholinergics, opioids.","Benzodiazepínicos e sedativos."],["1gf59li1r","What is pharmacogenomics?","Study of how genetic variation affects drug response and toxicity.","Genética da resposta a drogas."],["xuyfdk1co","What is the purpose of therapeutic drug monitoring?","Adjust doses of drugs with narrow therapeutic index or variable kinetics.","Ajustar dose por níveis."],["v35dfijpu","What does the steady-state concentration depend on?","Dosing rate and clearance (not loading dose).","Taxa de dose e depuração."],["1byo2zz18","What is the effect of doubling the infusion rate on time to steady state?","No change in time (still 4-5 half-lives); steady-state concentration doubles.","Tempo igual; concentração dobra."],["z171jdnxd","What is the definition of an agonist?","Drug that binds a receptor and activates it.","Ativa o receptor."],["1k2flqqm6","What is the definition of an antagonist?","Drug that binds a receptor without activating it, blocking agonists.","Bloqueia o receptor."],["hfxwjn1d0","What is an irreversible antagonist example?","Phenoxybenzamine (alpha), aspirin (COX enzyme).","Fenoxibenzamina."],["jb042r1cj","What is a physiologic antagonist?","Drug producing opposite effects through a different receptor (glucagon vs insulin; epinephrine vs histamine).","Efeito oposto por outro receptor."],["a413vh1i7","What is a chemical antagonist?","Drug that binds and inactivates another drug directly (protamine binding heparin).","Neutraliza diretamente."]]},{"name":"Toxicities & Side Effects","cards":[["vkq1c9min","What is the antidote for acetaminophen toxicity?","N-acetylcysteine.","N-acetilcisteína."],["1t93r7ab7","What is the antidote for AChE inhibitors and organophosphates?","Atropine and pralidoxime.","Atropina e pralidoxima."],["8hjyn919y","What is the antidote for antimuscarinic and anticholinergic toxicity?","Physostigmine (and control hyperthermia).","Fisostigmina."],["cm0obw1hy","What is the antidote for arsenic toxicity?","Dimercaprol, succimer.","Dimercaprol."],["iz3df2rs4","What is the antidote for benzodiazepine overdose?","Flumazenil (caution: seizures in chronic users).","Flumazenil."],["16ksz0v1t","Why does glucagon work in beta-blocker overdose?","It increases cAMP in cardiac cells through its own receptor, bypassing the blocked beta receptors.","Aumenta AMPc sem passar pelo receptor beta."],["vy2zqcnir","What is the antidote for carbon monoxide poisoning?","100% oxygen, hyperbaric oxygen.","Oxigênio 100% ou hiperbárico."],["4vcpvb6dr","What is the antidote for copper, arsenic, gold toxicity?","Penicillamine (copper), dimercaprol and succimer.","Penicilamina e dimercaprol."],["cx8zi14e0","What is the antidote for cyanide poisoning?","Hydroxocobalamin, nitrites plus sodium thiosulfate.","Hidroxocobalamina."],["1anxmblm0","What is the antidote for dabigatran?","Idarucizumab.","Idarucizumabe."],["8yrwt31d8","What is the antidote for digoxin toxicity?","Digoxin-specific antibody fragments (Fab), correct electrolytes.","Anticorpos antidigoxina."],["12icoi61f","What is the antidote for direct factor Xa inhibitors?","Andexanet alfa.","Andexanete alfa."],["1ftp4ix1d","What is the antidote for heparin?","Protamine sulfate.","Protamina."],["13vzb7b1z","What is the antidote for iron toxicity?","Deferoxamine (deferasirox for chronic overload).","Deferoxamina."],["16hmmtk8a","What is the antidote for lead poisoning?","Calcium disodium EDTA, dimercaprol, succimer (children), penicillamine.","EDTA e succímero."],["q489hfmn2","What is the antidote for mercury poisoning?","Dimercaprol, succimer.","Dimercaprol."],["16fwtw543","What is the antidote for methanol or ethylene glycol?","Fomepizole (alcohol dehydrogenase inhibitor), dialysis.","Fomepizol."],["zeq1siav8","What is the antidote for methemoglobinemia?","Methylene blue, vitamin C.","Azul de metileno."],["1h4qohzwu","What is the antidote for opioid overdose?","Naloxone.","Naloxona."],["14994o21j","What is the antidote for salicylate overdose?","Sodium bicarbonate (urine alkalinization), dialysis.","Bicarbonato."],["mytyedqb7","What is the antidote for TCA overdose?","Sodium bicarbonate (for wide QRS and arrhythmias).","Bicarbonato de sódio."],["1g19keu1i","What is the antidote for warfarin?","Vitamin K, plus prothrombin complex concentrate or FFP for rapid reversal.","Vitamina K e complexo protrombínico."],["142n7tw1y","What is the antidote for tPA and streptokinase bleeding?","Aminocaproic acid or tranexamic acid.","Ácido aminocaproico."],["1ehfjb11j","What is the antidote for methotrexate toxicity?","Leucovorin (folinic acid); glucarpidase for high levels.","Leucovorina."],["18yf51f11","What is the antidote for malignant hyperthermia?","Dantrolene.","Dantroleno."],["1vyi98s3f","What is the antidote for serotonin syndrome?","Cyproheptadine (5-HT2 antagonist), benzodiazepines, cooling.","Ciproeptadina."],["fr353rbjs","What is the antidote for isoniazid overdose?","Pyridoxine (vitamin B6).","Piridoxina."],["pfoxl41yf","What is the antidote for sulfonylurea overdose?","Octreotide (with glucose).","Octreotida."],["zbb69eh2q","What is the antidote for calcium channel blocker overdose?","Calcium, high-dose insulin with glucose.","Cálcio e insulina."],["tn2wbiji2","What is the antidote for local anesthetic toxicity?","Lipid emulsion.","Emulsão lipídica."],["fct7qr12o","Which drugs cause coronary vasospasm?","Cocaine, amphetamines, sumatriptan, ergot alkaloids.","Cocaína e triptanos."],["lctl1w4ct","Which drugs cause cutaneous flushing?","Vancomycin, adenosine, niacin, calcium channel blockers, echinocandins, nitrates (VANCE).","Vancomicina, adenosina, niacina."],["ykd2xl1o9","Which drugs cause dilated cardiomyopathy?","Anthracyclines (doxorubicin), trastuzumab, alcohol, cocaine.","Doxorrubicina e trastuzumabe."],["15bc42rmv","Which drugs cause torsades de pointes?","Antiarrhythmics (IA and III), antibiotics (macrolides, fluoroquinolones), antipsychotics (haloperidol), antidepressants (TCAs), antiemetics (ondansetron), methadone.","Antiarrítmicos, macrolídeos, antipsicóticos."],["1dbhyu4fv","Which drugs cause adrenocortical insufficiency?","Abrupt withdrawal of exogenous glucocorticoids; etomidate.","Retirada de corticoide."],["rp7dy6tk0","Which drugs cause diabetes insipidus?","Lithium, demeclocycline.","Lítio e demeclociclina."],["1v7qy6j16","Which drugs cause gynecomastia?","Spironolactone, digoxin, cimetidine, chronic alcohol, estrogens, ketoconazole, GnRH analogs (Some Drugs Create Awesome Knockers).","Espironolactona, digoxina, cimetidina."],["au19iusro","Which drugs cause hyperglycemia?","Tacrolimus, protease inhibitors, niacin, hydrochlorothiazide, glucocorticoids (The People Need Hard Candy).","Corticoide e tiazídicos."],["wykof13te","Which drugs cause hypothyroidism?","Lithium, amiodarone, sulfonamides.","Lítio e amiodarona."],["1a1j5iehs","Which drugs cause SIADH?","Carbamazepine, cyclophosphamide, SSRIs, vincristine, chlorpropamide.","Carbamazepina e ISRS."],["dv78d9ay2","Which drugs cause acute cholestatic hepatitis and jaundice?","Erythromycin estolate, amoxicillin-clavulanate, anabolic steroids, OCPs.","Eritromicina e anabolizantes."],["v6x9go11t","Which drugs cause pancreatitis?","Diuretics, glucocorticoids, alcohol, valproate, azathioprine, didanosine, GLP-1 agonists.","Valproato e azatioprina."],["1spdvdp1n","Which drugs cause pseudomembranous colitis?","Clindamycin, ampicillin, cephalosporins, fluoroquinolones, PPIs.","Clindamicina."],["u4c1qsun9","Which drugs cause agranulocytosis?","Clozapine, carbamazepine, colchicine, methimazole, propylthiouracil, dapsone, ganciclovir.","Clozapina, carbamazepina, metimazol."],["14y3z1r18","Which drugs cause aplastic anemia?","Carbamazepine, methimazole, NSAIDs, benzene, chloramphenicol, propylthiouracil.","Cloranfenicol e carbamazepina."],["11sn2z2nr","Which drugs cause direct Coombs-positive hemolytic anemia?","Penicillin, methyldopa, cephalosporins.","Penicilina e metildopa."],["1bnv5yt22","Which drugs cause hemolysis in G6PD deficiency?","Isoniazid, sulfonamides, dapsone, primaquine, aspirin, ibuprofen, nitrofurantoin, rasburicase.","Sulfas, primaquina, dapsona."],["1jhyu35su","Which drugs cause megaloblastic anemia?","Hydroxyurea, phenytoin, methotrexate, sulfa drugs, trimethoprim.","Metotrexato e fenitoína."],["1y35n0i1d","Which drugs cause thrombocytopenia?","Heparin (HIT), quinidine, linezolid, valproate.","Heparina."],["19w1t7b64","Which drugs cause thrombotic complications?","Combined oral contraceptives, hormone replacement therapy, SERMs, epoetin.","Anticoncepcionais e tamoxifeno."],["1ifmm5r46","Which drugs cause fat redistribution?","Protease inhibitors, glucocorticoids.","Inibidores de protease e corticoide."],["wpgstwje8","Which drugs cause gingival hyperplasia?","Phenytoin, calcium channel blockers (verapamil, nifedipine), cyclosporine.","Fenitoína, bloqueadores de cálcio, ciclosporina."],["1mv7t8iar","Which drugs cause hyperuricemia (gout)?","Pyrazinamide, thiazides, furosemide, niacin, cyclosporine.","Pirazinamida e diuréticos."],["1wz08lar0","Which drugs cause myopathy?","Statins, fibrates, niacin, colchicine, daptomycin, hydroxychloroquine, interferon-alpha, penicillamine, glucocorticoids.","Estatinas e fibratos."],["1dphzug7b","Which drugs cause osteoporosis?","Glucocorticoids, depot medroxyprogesterone, GnRH agonists, aromatase inhibitors, anticonvulsants, heparin, PPIs.","Corticoides."],["1rqdy3414","Which drugs cause photosensitivity?","Sulfonamides, amiodarone, tetracyclines, 5-FU (SAT For Photo).","Sulfas, amiodarona, tetraciclinas."],["1nivssd1a","Which drugs cause rash (Stevens-Johnson syndrome)?","Anti-epileptics (lamotrigine), allopurinol, sulfa drugs, penicillin.","Lamotrigina, alopurinol, sulfas."],["1gsnrz718","Which drugs cause drug-induced lupus?","Methyldopa, minocycline, hydralazine, isoniazid, phenytoin, procainamide, TNF inhibitors.","Hidralazina e procainamida."],["eb2ykt1o8","Which drugs cause interstitial nephritis?","Diuretics, NSAIDs, penicillins and cephalosporins, PPIs, rifampin, sulfa drugs.","AINEs, penicilinas, IBP."],["1e0du7481","Which drugs cause hemorrhagic cystitis?","Cyclophosphamide, ifosfamide (prevent with mesna).","Ciclofosfamida."],["1xiali63i","Which drugs cause Fanconi syndrome?","Cisplatin, ifosfamide, expired tetracyclines, tenofovir.","Cisplatina e tenofovir."],["1qfvu4n1a","Which drugs cause pulmonary fibrosis?","Methotrexate, nitrofurantoin, carmustine, bleomycin, busulfan, amiodarone (My Nose Cannot Breathe Bad Air).","Bleomicina e amiodarona."],["1pcuh2gej","Which drugs cause dry cough?","ACE inhibitors.","IECA."],["kqwyg512b","Which drugs cause seizures?","Isoniazid, bupropion, imipenem, tramadol, enflurane (with B6 deficiency).","Isoniazida, bupropiona, imipeném."],["1er0590h0","Which drugs cause tardive dyskinesia?","Antipsychotics, metoclopramide.","Antipsicóticos e metoclopramida."],["13ey24w1b","Which drugs cause visual disturbances?","Hydroxychloroquine (retinopathy), ethambutol (optic neuropathy), digoxin (yellow vision), sildenafil (blue vision), vigabatrin (field loss).","Hidroxicloroquina, etambutol, digoxina."],["1rf534ivj","Which drugs cause anticholinergic effects?","Atropine, TCAs, H1 blockers, antipsychotics, oxybutynin.","Atropina e tricíclicos."],["qg36bfnm6","Which drugs cause disulfiram-like reactions?","Metronidazole, certain cephalosporins, griseofulvin, procarbazine, first-generation sulfonylureas.","Metronidazol."],["1ik3rea12","Which drugs cause nephrotoxicity?","Aminoglycosides, vancomycin, amphotericin B, cisplatin, cidofovir, foscarnet, NSAIDs, contrast, tacrolimus, cyclosporine.","Aminoglicosídeos, anfotericina, cisplatina."],["18svwy037","Which drugs cause ototoxicity?","Aminoglycosides, loop diuretics, cisplatin, vancomycin (rare), salicylates (tinnitus).","Aminoglicosídeos e furosemida."],["rds0681sd","Which drugs cause QT prolongation and are used in addiction treatment?","Methadone.","Metadona."],["1lne729ol","Which drugs cause hyperkalemia?","ACE inhibitors, ARBs, potassium-sparing diuretics, trimethoprim, heparin, succinylcholine, digoxin toxicity, NSAIDs, beta-blockers, tacrolimus.","IECA, espironolactona, trimetoprima."],["oq2uuxh11","Which drugs cause hypokalemia?","Loop and thiazide diuretics, beta2 agonists, insulin, amphotericin B.","Diuréticos e insulina."],["w7bkie1xu","Which drugs cause hyponatremia?","Thiazides, SSRIs, carbamazepine, oxcarbazepine, cyclophosphamide, desmopressin.","Tiazídicos e ISRS."],["1p1pkh4vo","Which drugs cause lactic acidosis?","Metformin, NRTIs (especially older ones), propofol infusion, linezolid.","Metformina."],["1pou03ytw","Which drugs cause hypoglycemia?","Insulin, sulfonylureas, meglitinides, beta-blockers (masking), alcohol, quinine, pentamidine.","Insulina e sulfonilureias."],["h5w1561xv","Which drugs cause peripheral neuropathy?","Isoniazid, vincristine, paclitaxel, cisplatin, metronidazole, nitrofurantoin, phenytoin, linezolid, bortezomib.","Isoniazida e vincristina."],["xpdzuw1kn","Which drugs cause cinchonism?","Quinidine and quinine: headache, tinnitus, vertigo, visual changes.","Quinidina."],["zl0zgj1cm","Which drugs cause osteonecrosis of the jaw?","Bisphosphonates and denosumab.","Bisfosfonatos."],["9xnmnqfdf","Which drugs cause tendinopathy?","Fluoroquinolones (especially with steroids).","Fluoroquinolonas."],["uv5frct8m","Which drugs cause teeth discoloration?","Tetracyclines.","Tetraciclinas."],["v9xvuid6a","Which drugs cause red-orange urine?","Rifampin and phenazopyridine.","Rifampicina."],["i73zfr1el","Which drugs cause hirsutism?","Minoxidil, cyclosporine, phenytoin, glucocorticoids, androgens.","Minoxidil e ciclosporina."],["1213ur11v","Which drugs cause alopecia?","Chemotherapy, valproate, warfarin, lithium (with hypothyroidism).","Quimioterapia e valproato."],["hykdm83vv","Which drugs cause weight gain?","Antipsychotics (olanzapine, clozapine), mirtazapine, TCAs, lithium, valproate, insulin, sulfonylureas, glucocorticoids.","Olanzapina e mirtazapina."],["z76c81ncl","Which drugs cause erectile dysfunction?","Beta-blockers, thiazides, SSRIs, antipsychotics, spironolactone, finasteride.","Betabloqueadores e ISRS."],["bf0n7l1f2","What are the symptoms of lead poisoning (LEAD mnemonic)?","Lead lines on gingivae and long bones, Encephalopathy and Erythrocyte basophilic stippling, Abdominal colic and sideroblastic Anemia, Drops (wrist and foot drop).","Linhas de chumbo, encefalopatia, cólica, queda de punho."],["1sssfwnjd","What are the symptoms of mercury poisoning?","Acrodynia (pink painful extremities), neurologic symptoms (erethism: shyness, irritability), renal damage.","Acrodinia e alterações neurológicas."],["r0mwe91pb","What are the symptoms of arsenic poisoning?","Garlic breath, rice-water diarrhea, QT prolongation, Mees lines on nails, hyperpigmentation, skin cancer.","Hálito de alho e linhas nas unhas."],["ch6bzxx0f","What are the symptoms of cyanide poisoning?","Almond breath odor, confusion, seizures, lactic acidosis, cherry-red skin; elevated venous O2 saturation.","Odor de amêndoa e acidose lática."]]}];
